package org.eclipse.kura.core.keystore;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assume.assumeTrue;

import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.SyncFailedException;
import java.nio.charset.StandardCharsets;
import java.nio.file.FileSystemException;
import java.nio.file.FileSystems;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.attribute.PosixFilePermission;
import java.nio.file.attribute.PosixFilePermissions;
import java.security.GeneralSecurityException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Set;

import org.junit.Test;

public class AtomicFileWriteTest extends AbstractAtomicFileWriterTest {

    private Exception simulatedFailure;
    private final List<String> operations = new ArrayList<>();

    @Test
    public void writesContentToNewFile() throws Exception {
        givenTargetFile("data.bin");

        whenContentIsWritten(this.target, "new content");

        thenNoExceptionIsThrown();
        thenFileContains("data.bin", "new content");
        thenDirectoryContainsOnly("data.bin");
    }

    @Test
    public void replacesContentOfExistingFile() throws Exception {
        givenTargetFile("data.bin", "old content");

        whenContentIsWritten(this.target, "new content");

        thenNoExceptionIsThrown();
        thenFileContains("data.bin", "new content");
        thenDirectoryContainsOnly("data.bin");
    }

    @Test
    public void rejectsNullTarget() {
        givenNullTarget();

        whenContentIsWritten(this.target, "new content");

        thenExceptionIsThrown(IllegalArgumentException.class);
        thenDirectoryContainsOnly();
    }

    @Test
    public void rejectsNullContent() throws Exception {
        givenTargetFile("data.bin", "old content");

        whenNullContentIsWritten();

        thenExceptionIsThrown(IllegalArgumentException.class);
        thenFileContains("data.bin", "old content");
        thenDirectoryContainsOnly("data.bin");
    }

    @Test
    public void rejectsEmptyDirectoryAsTarget() throws Exception {
        givenTargetDirectory("data.bin");

        whenContentIsWritten(this.target, "new content");

        thenExceptionIsThrown(FileSystemException.class);
        thenDirectoryContainsOnly("data.bin");
        thenTargetIsDirectoryContainingOnly();
    }

    @Test
    public void rejectsNonEmptyDirectoryAsTarget() throws Exception {
        givenTargetDirectory("data.bin");
        givenFileInTargetDirectory("entry.txt", "entry content");

        whenContentIsWritten(this.target, "new content");

        thenExceptionIsThrown(FileSystemException.class);
        thenDirectoryContainsOnly("data.bin");
        thenTargetIsDirectoryContainingOnly("entry.txt");
        thenFileContains("data.bin/entry.txt", "entry content");
    }

    @Test
    public void writesOwnerOnlyFilesByDefault() throws Exception {
        givenPosixFileSystem();
        givenTargetFile("data.bin", "old content");
        givenTargetPermissions("rw-r--r--");

        whenContentIsWritten(this.target, "new content");

        thenNoExceptionIsThrown();
        thenFileHasPermissions("data.bin", "rw-------");
    }

    @Test
    public void writesFilesWithConfiguredPermissions() throws Exception {
        givenPosixFileSystem();
        givenWriterWithPermissions("rw-r-----");
        givenTargetFile("data.bin", "old content");

        whenContentIsWritten(this.target, "new content");

        thenNoExceptionIsThrown();
        thenFileHasPermissions("data.bin", "rw-r-----");
    }

    @Test
    public void rejectsNullPermissions() {
        whenWriterIsCreatedWithPermissions(null);

        thenExceptionIsThrown(IllegalArgumentException.class);
    }

    @Test
    public void keepsTargetWhenContentFails() throws Exception {
        givenTargetFile("data.bin", "old content");

        whenFailingContentIsWritten(this.target);

        thenSimulatedFailureIsThrown();
        thenFileContains("data.bin", "old content");
        thenDirectoryContainsOnly("data.bin");
    }

    @Test
    public void keepsTargetWhenContentThrowsCheckedException() throws Exception {
        givenTargetFile("data.bin", "old content");

        whenContentThrowingCheckedExceptionIsWritten(this.target);

        thenSimulatedFailureIsThrown();
        thenFileContains("data.bin", "old content");
        thenDirectoryContainsOnly("data.bin");
    }

    @Test
    public void keepsTargetWhenSyncFails() throws Exception {
        givenTargetFile("data.bin", "old content");
        givenSyncFails();

        whenContentIsWritten(this.target, "new content");

        thenSimulatedFailureIsThrown();
        thenFileContains("data.bin", "old content");
        thenDirectoryContainsOnly("data.bin");
    }

    @Test
    public void keepsTargetWhenMoveFails() throws Exception {
        givenTargetFile("data.bin", "old content");
        givenMoveFails();

        whenContentIsWritten(this.target, "new content");

        thenSimulatedFailureIsThrown();
        thenFileContains("data.bin", "old content");
        thenDirectoryContainsOnly("data.bin");
    }

    @Test
    public void syncsDirectoryAfterMove() throws Exception {
        givenTargetFile("data.bin", "old content");
        givenWriterRecordingMovesAndDirectorySyncs();

        whenContentIsWritten(this.target, "new content");

        thenNoExceptionIsThrown();
        thenOperationsAre("move data.bin", "sync directory");
    }

    @Test
    public void notReportsFailureWhenDirectorySyncFails() throws Exception {
        givenTargetFile("data.bin", "old content");
        givenDirectorySyncFails();

        whenContentIsWritten(this.target, "new content");

        thenNoExceptionIsThrown();
        thenFileContains("data.bin", "new content");
        thenDirectoryContainsOnly("data.bin");
    }

    @Test
    public void writesThroughSymlinkedTarget() throws Exception {
        givenPosixFileSystem();
        givenDirectory("real");
        givenFile("real/data.bin", "old content");
        givenTargetSymlinkTo("data.bin", "real/data.bin");

        whenContentIsWritten(this.target, "new content");

        thenNoExceptionIsThrown();
        thenIsSymlinkTo("data.bin", "real/data.bin");
        thenFileContains("real/data.bin", "new content");
        thenDirectoryContainsOnly("data.bin", "real");
        thenSubdirectoryContainsOnly("real", "data.bin");
    }

    @Test
    public void rejectsDanglingSymlinkAsTarget() throws Exception {
        givenPosixFileSystem();
        givenTargetSymlinkTo("data.bin", "missing.bin");

        whenContentIsWritten(this.target, "new content");

        thenFileSystemExceptionIsThrownFor("data.bin");
        thenIsSymlinkTo("data.bin", "missing.bin");
        thenDirectoryContainsOnly("data.bin");
    }

    private void givenTargetSymlinkTo(final String name, final String linkTarget) throws IOException {
        givenTargetFile(name);
        Files.createSymbolicLink(this.target, Paths.get(linkTarget));
    }

    private void givenSyncFails() {
        final IOException failure = new SyncFailedException("simulated sync failure");
        this.simulatedFailure = failure;
        this.writer = new AtomicFileWriter() {

            @Override
            void sync(final FileOutputStream out) throws IOException {
                throw failure;
            }
        };
    }

    private void givenWriterRecordingMovesAndDirectorySyncs() throws IOException {
        final Path directory = this.folder.getRoot().toPath().toRealPath();
        this.writer = new AtomicFileWriter() {

            @Override
            void atomicMove(final Path source, final Path destination) throws IOException {
                AtomicFileWriteTest.this.operations.add("move " + destination.getFileName());
                super.atomicMove(source, destination);
            }

            @Override
            void syncDirectory(final Path synced) throws IOException {
                AtomicFileWriteTest.this.operations
                        .add(directory.equals(synced.toRealPath()) ? "sync directory" : "sync " + synced);
                super.syncDirectory(synced);
            }
        };
    }

    private void givenDirectorySyncFails() {
        final IOException failure = new IOException("simulated directory sync failure");
        this.simulatedFailure = failure;
        this.writer = new AtomicFileWriter() {

            @Override
            void syncDirectory(final Path directory) throws IOException {
                throw failure;
            }
        };
    }

    private void givenMoveFails() {
        final IOException failure = new IOException("simulated move failure");
        this.simulatedFailure = failure;
        this.writer = new AtomicFileWriter() {

            @Override
            void atomicMove(final Path source, final Path destination) throws IOException {
                throw failure;
            }
        };
    }

    private void givenPosixFileSystem() {
        assumeTrue(FileSystems.getDefault().supportedFileAttributeViews().contains("posix"));
    }

    private void givenWriterWithPermissions(final String permissions) {
        this.writer = new AtomicFileWriter(PosixFilePermissions.fromString(permissions));
    }

    private void givenTargetPermissions(final String permissions) throws IOException {
        Files.setPosixFilePermissions(this.target, PosixFilePermissions.fromString(permissions));
    }

    private void givenFileInTargetDirectory(final String name, final String content) throws Exception {
        Files.write(this.target.resolve(name), content.getBytes(StandardCharsets.UTF_8));
    }

    private void whenContentIsWritten(final Path target, final String content) {
        try {
            this.writer.write(target, out -> out.write(content.getBytes(StandardCharsets.UTF_8)));
        } catch (Exception e) {
            this.exception = e;
        }
    }

    private void whenWriterIsCreatedWithPermissions(final Set<PosixFilePermission> permissions) {
        try {
            this.writer = new AtomicFileWriter(permissions);
        } catch (Exception e) {
            this.exception = e;
        }
    }

    private void whenFailingContentIsWritten(final Path target) {
        final IOException failure = new IOException("simulated content failure");
        this.simulatedFailure = failure;
        try {
            this.writer.write(target, out -> {
                out.write("partial".getBytes(StandardCharsets.UTF_8));
                throw failure;
            });
        } catch (Exception e) {
            this.exception = e;
        }
    }

    private void whenContentThrowingCheckedExceptionIsWritten(final Path target) {
        final GeneralSecurityException failure = new GeneralSecurityException("simulated checked failure");
        this.simulatedFailure = failure;
        try {
            this.writer.write(target, out -> {
                out.write("partial".getBytes(StandardCharsets.UTF_8));
                throw failure;
            });
        } catch (Exception e) {
            this.exception = e;
        }
    }

    private void whenNullContentIsWritten() {
        try {
            this.writer.write(this.target, null);
        } catch (Exception e) {
            this.exception = e;
        }
    }

    private void thenOperationsAre(final String... expectedOperations) {
        assertEquals(Arrays.asList(expectedOperations), this.operations);
    }

    private void thenSimulatedFailureIsThrown() {
        assertSame(this.simulatedFailure, this.exception);
    }

    private void thenFileSystemExceptionIsThrownFor(final String name) throws IOException {
        thenExceptionIsThrown(FileSystemException.class);
        final File expected = new File(this.folder.getRoot(), name);
        final File actual = new File(((FileSystemException) this.exception).getFile());
        assertEquals(expected.getName(), actual.getName());
        assertEquals(expected.getParentFile().getCanonicalPath(), actual.getParentFile().getCanonicalPath());
    }

    private void thenIsSymlinkTo(final String name, final String linkTarget) throws IOException {
        final Path link = new File(this.folder.getRoot(), name).toPath();
        assertTrue(name + " should still be a symbolic link", Files.isSymbolicLink(link));
        assertEquals(Paths.get(linkTarget), Files.readSymbolicLink(link));
    }

    private void thenSubdirectoryContainsOnly(final String directory, final String... expectedNames) {
        final String[] actualNames = new File(this.folder.getRoot(), directory).list();
        Arrays.sort(actualNames);
        Arrays.sort(expectedNames);
        assertEquals(Arrays.asList(expectedNames), Arrays.asList(actualNames));
    }

    private void thenFileHasPermissions(final String name, final String expected) throws Exception {
        final Path file = new File(this.folder.getRoot(), name).toPath();
        assertEquals(name + " permissions", expected,
                PosixFilePermissions.toString(Files.getPosixFilePermissions(file)));
    }

    private void thenTargetIsDirectoryContainingOnly(final String... expectedNames) {
        assertTrue(this.target + " should still be a directory", Files.isDirectory(this.target));
        final String[] actualNames = this.target.toFile().list();
        Arrays.sort(actualNames);
        Arrays.sort(expectedNames);
        assertEquals(Arrays.asList(expectedNames), Arrays.asList(actualNames));
    }
}
